package com.aaliyun.leadnews.article.service;
import com.aaliyun.leadnews.article.config.AiSummaryProperties;import com.aaliyun.leadnews.article.domain.*;import com.aaliyun.leadnews.article.mapper.*;import com.aaliyun.leadnews.common.api.CommonErrorCode;import com.aaliyun.leadnews.common.context.UserContext;import com.aaliyun.leadnews.common.exception.BusinessException;import com.aaliyun.leadnews.common.trace.TraceContext;import com.aaliyun.leadnews.feign.ai.AiInternalClient;import com.aaliyun.leadnews.model.ai.*;import com.aaliyun.leadnews.model.foundation.ArticleContentItemDTO;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import io.micrometer.core.instrument.MeterRegistry;import org.slf4j.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import java.util.concurrent.TimeUnit;
@Service public class ArticleAiSummaryService{private static final Logger log=LoggerFactory.getLogger(ArticleAiSummaryService.class);private final ArticleMapper articles;private final ArticleContentMapper contents;private final ArticleAiSummaryTaskMapper tasks;private final AiInternalClient ai;private final KafkaTemplate<String,Object> kafka;private final ObjectMapper json;private final AiSummaryProperties p;private final MeterRegistry metrics;
 public ArticleAiSummaryService(ArticleMapper a,ArticleContentMapper c,ArticleAiSummaryTaskMapper t,AiInternalClient ai,KafkaTemplate<String,Object> k,ObjectMapper j,AiSummaryProperties p,MeterRegistry m){articles=a;contents=c;tasks=t;this.ai=ai;kafka=k;json=j;this.p=p;metrics=m;}
 @Transactional public void enqueuePublished(Long id){if(!p.enabled())return;Article a=articles.selectById(id);if(a==null||!"PUBLISHED".equals(a.getPublishStatus()))return;long old=a.getSummaryVersion()==null?0:a.getSummaryVersion();int n=articles.update(null,new LambdaUpdateWrapper<Article>().eq(Article::getId,id).eq(Article::getSummaryVersion,old).eq(Article::getPublishStatus,"PUBLISHED").setSql("summary_version = summary_version + 1").set(Article::getSummaryStatus,"PENDING").set(Article::getSummary,null).set(Article::getSummaryModel,null).set(Article::getSummaryGeneratedTime,null));if(n!=1)return;createTask(id,old+1);}
 private void createTask(Long id,long version){ArticleAiSummaryTask t=new ArticleAiSummaryTask();t.setArticleId(id);t.setSummaryVersion(version);t.setEventId(UUID.randomUUID().toString());t.setStatus("PENDING");t.setRetryCount(0);t.setNextRetryTime(LocalDateTime.now());t.setTraceId(TraceContext.getTraceId());tasks.insert(t);}
 @Scheduled(fixedDelayString="${leadnews.ai.summary.dispatch-interval-ms:5000}") public void dispatch(){if(!p.enabled())return;var rows=tasks.selectList(new LambdaQueryWrapper<ArticleAiSummaryTask>().in(ArticleAiSummaryTask::getStatus,List.of("PENDING","FAILED")).le(ArticleAiSummaryTask::getNextRetryTime,LocalDateTime.now()).lt(ArticleAiSummaryTask::getRetryCount,p.maxRetries()).orderByAsc(ArticleAiSummaryTask::getId).last("LIMIT 50"));rows.forEach(this::send);}
 private void send(ArticleAiSummaryTask t){String prior=t.getStatus();try{Article a=articles.selectById(t.getArticleId());Instant pub=(a.getPublishedTime()==null?a.getPublishTime():a.getPublishedTime()).atZone(ZoneId.systemDefault()).toInstant();var e=new ArticlePublishedEvent(t.getEventId(),t.getArticleId(),t.getSummaryVersion(),pub,t.getCreatedTime().atZone(ZoneId.systemDefault()).toInstant(),t.getTraceId());kafka.send("leadnews.article.published",t.getArticleId().toString(),e).get(10,TimeUnit.SECONDS);tasks.update(null,new LambdaUpdateWrapper<ArticleAiSummaryTask>().eq(ArticleAiSummaryTask::getId,t.getId()).eq(ArticleAiSummaryTask::getStatus,prior).set(ArticleAiSummaryTask::getStatus,"SENT"));}catch(Exception e){String error=safe(e);log.warn("ai_summary_dispatch success=false articleId={} summaryVersion={} errorCode={}",t.getArticleId(),t.getSummaryVersion(),error);tasks.update(null,new LambdaUpdateWrapper<ArticleAiSummaryTask>().eq(ArticleAiSummaryTask::getId,t.getId()).eq(ArticleAiSummaryTask::getStatus,prior).set(ArticleAiSummaryTask::getStatus,"FAILED").set(ArticleAiSummaryTask::getNextRetryTime,LocalDateTime.now().plusSeconds(5)).set(ArticleAiSummaryTask::getLastError,error));}}
 @KafkaListener(topics="leadnews.article.published",groupId="leadnews-article-summary-v1") public void consume(ArticlePublishedEvent e){ArticleAiSummaryTask t=tasks.selectOne(new LambdaQueryWrapper<ArticleAiSummaryTask>().eq(ArticleAiSummaryTask::getEventId,e.eventId()).eq(ArticleAiSummaryTask::getArticleId,e.articleId()).eq(ArticleAiSummaryTask::getSummaryVersion,e.summaryVersion()));if(t==null||!claim(t))return;long start=System.nanoTime();try{Article a=articles.selectById(e.articleId());if(a==null||!"PUBLISHED".equals(a.getPublishStatus())||!Objects.equals(a.getSummaryVersion(),e.summaryVersion())){finishTask(t,"STALE",null);return;}ArticleContent c=contents.selectOne(new LambdaQueryWrapper<ArticleContent>().eq(ArticleContent::getArticleId,a.getId()));String text=readText(c);ArticleSummaryResponse r=ai.summarize(new ArticleSummaryRequest(a.getId(),e.summaryVersion(),a.getTitle(),a.getLabels(),text));String summary=validate(r.summary(),text);int n=articles.update(null,new LambdaUpdateWrapper<Article>().eq(Article::getId,a.getId()).eq(Article::getSummaryVersion,e.summaryVersion()).eq(Article::getPublishStatus,"PUBLISHED").set(Article::getSummary,summary).set(Article::getSummaryStatus,"SUCCESS").set(Article::getSummaryModel,r.model()).set(Article::getSummaryGeneratedTime,LocalDateTime.now()));finishTask(t,n==1?"SUCCESS":"STALE",null);if(n==1){metrics.counter("ai.summary.success").increment();metrics.timer("ai.summary.latency").record(Duration.ofNanos(System.nanoTime()-start));}}catch(Exception x){fail(t,x);}}
 private boolean claim(ArticleAiSummaryTask t){LocalDateTime stale=LocalDateTime.now().minus(p.runningTimeout());int n=tasks.update(null,new LambdaUpdateWrapper<ArticleAiSummaryTask>().eq(ArticleAiSummaryTask::getId,t.getId()).lt(ArticleAiSummaryTask::getRetryCount,p.maxRetries()).and(w->w.in(ArticleAiSummaryTask::getStatus,List.of("PENDING","SENT","FAILED")).or(q->q.eq(ArticleAiSummaryTask::getStatus,"RUNNING").lt(ArticleAiSummaryTask::getStartedTime,stale))).set(ArticleAiSummaryTask::getStatus,"RUNNING").set(ArticleAiSummaryTask::getStartedTime,LocalDateTime.now()).set(ArticleAiSummaryTask::getLastError,null));if(n==1)articles.update(null,new LambdaUpdateWrapper<Article>().eq(Article::getId,t.getArticleId()).eq(Article::getSummaryVersion,t.getSummaryVersion()).eq(Article::getPublishStatus,"PUBLISHED").set(Article::getSummaryStatus,"GENERATING"));return n==1;}
 private void fail(ArticleAiSummaryTask t,Exception x){int retry=t.getRetryCount()+1;tasks.update(null,new LambdaUpdateWrapper<ArticleAiSummaryTask>().eq(ArticleAiSummaryTask::getId,t.getId()).eq(ArticleAiSummaryTask::getStatus,"RUNNING").set(ArticleAiSummaryTask::getStatus,"FAILED").set(ArticleAiSummaryTask::getRetryCount,retry).set(ArticleAiSummaryTask::getNextRetryTime,LocalDateTime.now().plusSeconds(Math.min(60,1L<<Math.min(retry,5)))).set(ArticleAiSummaryTask::getLastError,safe(x)));articles.update(null,new LambdaUpdateWrapper<Article>().eq(Article::getId,t.getArticleId()).eq(Article::getSummaryVersion,t.getSummaryVersion()).eq(Article::getPublishStatus,"PUBLISHED").set(Article::getSummaryStatus,"FAILED"));metrics.counter("ai.summary.failed").increment();log.warn("ai_summary success=false articleId={} summaryVersion={} errorCode={}",t.getArticleId(),t.getSummaryVersion(),x.getClass().getSimpleName());}
 private void finishTask(ArticleAiSummaryTask t,String status,String error){tasks.update(null,new LambdaUpdateWrapper<ArticleAiSummaryTask>().eq(ArticleAiSummaryTask::getId,t.getId()).eq(ArticleAiSummaryTask::getStatus,"RUNNING").set(ArticleAiSummaryTask::getStatus,status).set(ArticleAiSummaryTask::getLastError,error));}
 public int recoverRunning(){LocalDateTime stale=LocalDateTime.now().minus(p.runningTimeout());return tasks.update(null,new LambdaUpdateWrapper<ArticleAiSummaryTask>().eq(ArticleAiSummaryTask::getStatus,"RUNNING").lt(ArticleAiSummaryTask::getStartedTime,stale).lt(ArticleAiSummaryTask::getRetryCount,p.maxRetries()).set(ArticleAiSummaryTask::getStatus,"FAILED").set(ArticleAiSummaryTask::getNextRetryTime,LocalDateTime.now()));}
 public int backfillPage(long page,int size){Page<Article> result=new Page<>(Math.max(1,page),Math.min(size,p.backfillPageSize()));articles.selectPage(result,new LambdaQueryWrapper<Article>().eq(Article::getPublishStatus,"PUBLISHED").in(Article::getSummaryStatus,List.of("NONE","FAILED")).orderByAsc(Article::getId));int n=0;for(Article a:result.getRecords()){enqueuePublished(a.getId());n++;}return n;}
 @Transactional public SummaryRetryResult retryFailed(Long articleId){if(!UserContext.isInternal())throw new BusinessException(CommonErrorCode.AUTH_FORBIDDEN);Article a=articles.selectById(articleId);if(a==null)throw new BusinessException(40400,"Article not found");if(!"PUBLISHED".equals(a.getPublishStatus()))throw new BusinessException(40900,"Only published articles can retry AI summary");if(Set.of("SUCCESS","PENDING","GENERATING").contains(a.getSummaryStatus()))return new SummaryRetryResult(articleId,a.getSummaryVersion(),a.getSummaryStatus(),false);if(!"FAILED".equals(a.getSummaryStatus()))throw new BusinessException(40900,"AI summary is not failed");long version=a.getSummaryVersion();ArticleAiSummaryTask task=tasks.selectOne(new LambdaQueryWrapper<ArticleAiSummaryTask>().eq(ArticleAiSummaryTask::getArticleId,articleId).eq(ArticleAiSummaryTask::getSummaryVersion,version));if(task==null)throw new BusinessException(40900,"AI summary task is missing");int articleChanged=articles.update(null,new LambdaUpdateWrapper<Article>().eq(Article::getId,articleId).eq(Article::getSummaryVersion,version).eq(Article::getPublishStatus,"PUBLISHED").eq(Article::getSummaryStatus,"FAILED").set(Article::getSummaryStatus,"PENDING"));if(articleChanged!=1){Article raced=articles.selectById(articleId);if(raced!=null&&"PUBLISHED".equals(raced.getPublishStatus())&&Objects.equals(raced.getSummaryVersion(),version)&&Set.of("PENDING","GENERATING","SUCCESS").contains(raced.getSummaryStatus()))return new SummaryRetryResult(articleId,version,raced.getSummaryStatus(),false);throw new BusinessException(40900,"AI summary state changed concurrently");}int taskChanged=tasks.update(null,new LambdaUpdateWrapper<ArticleAiSummaryTask>().eq(ArticleAiSummaryTask::getId,task.getId()).eq(ArticleAiSummaryTask::getArticleId,articleId).eq(ArticleAiSummaryTask::getSummaryVersion,version).eq(ArticleAiSummaryTask::getStatus,"FAILED").set(ArticleAiSummaryTask::getStatus,"PENDING").set(ArticleAiSummaryTask::getRetryCount,0).set(ArticleAiSummaryTask::getNextRetryTime,LocalDateTime.now()).set(ArticleAiSummaryTask::getStartedTime,null).set(ArticleAiSummaryTask::getLastError,null));if(taskChanged!=1)throw new BusinessException(40900,"AI summary task state changed concurrently");return new SummaryRetryResult(articleId,version,"PENDING",true);}
 public record SummaryRetryResult(Long articleId,Long summaryVersion,String summaryStatus,boolean reopened){}
 private String readText(ArticleContent c)throws Exception{if(c==null)throw new IllegalStateException("Article content missing");List<ArticleContentItemDTO> items=json.readValue(c.getContent(),new TypeReference<>(){});String s=items.stream().filter(i->"text".equalsIgnoreCase(i.type())).map(ArticleContentItemDTO::value).filter(Objects::nonNull).reduce("",(a,b)->a.isEmpty()?b:a+"\n"+b);if(s.isBlank())throw new IllegalStateException("Article text missing");return s;}
 private String validate(String s,String content){if(s==null)throw new IllegalStateException("Empty summary");String v=s.trim();for(String prefix:List.of("好的，以下是摘要：","以下是摘要：","摘要："))if(v.startsWith(prefix))v=v.substring(prefix.length()).trim();int min=Math.min(p.minLength(),Math.max(10,content.codePointCount(0,content.length())/2));if(v.length()<min||v.length()>p.maxLength())throw new IllegalStateException("Invalid summary length");return v;}
 private String safe(Exception e){StringJoiner names=new StringJoiner("->");Throwable current=e;String message=null;for(int i=0;i<5&&current!=null;i++){names.add(current.getClass().getSimpleName());message=current.getMessage();current=current.getCause();}String s=names+(message==null?"":":"+message.replaceAll("[\\r\\n]"," "));return s.substring(0,Math.min(500,s.length()));}
}
